// ratelimit/ratelimit.go
package ratelimit

import (
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	rate     float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given bucket capacity and refill rate
// (tokens per second). Both must be positive. A nil clock uses wall time.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("ratelimit: capacity must be > 0, got %v", capacity)
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimit: rate must be > 0, got %v", rate)
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens:   capacity,
		capacity: capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN attempts to consume n tokens. It returns true if the request is
// permitted, false otherwise. n must be non-negative.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

func (l *Limiter) refill() {
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.tokens+elapsed*l.rate, l.capacity)
		l.last = now
	}
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
